import{z as E,x as p,o as i,c as B,q as r,j as l,D as e,d as s,s as d,S as o,b as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"t-digest 与分位数","description":"","frontmatter":{"title":"t-digest 与分位数","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/t-digest-quantile.md","filePath":"cs/t-digest-quantile.md","lastUpdated":1791413859000}'),m={name:"cs/t-digest-quantile.md"};function g(c,a,u,A,h,D){const n=p("Mermaid");return i(),B("div",null,[a[2]||(a[2]=r('<h1 id="t-digest-与分位数" tabindex="-1">t-digest 与分位数 <a class="header-anchor" href="#t-digest-与分位数" aria-label="Permalink to &quot;t-digest 与分位数&quot;">​</a></h1><div class="epigraph"><p>用一组质心近似经验分布，两端的簇更小，使尾部分位数更准；合并质心可分布式求近似百分位。</p><footer>—— 据 Dunning and Ertl, Computing Extremely Accurate Quantiles Using t-Digests, 2019；Greenwald and Khanna, Space-Efficient Online Computation of Quantile Summaries, SIGMOD 2001 整理</footer></div><p><a href="/cs/reservoir-sampling">上一课</a> 均匀留 \\(k\\) 个点，估分位数方差随 \\(k\\)，尾部差。<a href="/cs/count-min-sketch">Count-Min</a> 不保序。精确百分位要排序或选择算法 \\(\\Theta(n)\\)。<a href="/cs/order-statistic-tree">顺序统计树</a> 要存全体。本课不替换蓄水池元素。缺口是流上分位数摘要：t-digest（及 GK 作为对照）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>查询近似 \\(q\\)-分位数，\\(\\varepsilon\\) 相对或绝对误差。GK 摘要：\\(\\Theta((1/\\varepsilon)\\log(\\varepsilon n))\\) 样本点。t-digest：质心 \\((m_i,c_i)\\)（均值与计数），规模限制函数让 \\(q\\) 近 \\(0\\) 或 \\(1\\) 时簇更细。插入：并入邻近质心或新建，过限则压缩。缺口是<strong>用可变宽度直方图换尾部精度</strong>，且 <code>merge</code> 自然。</p><p><span class="marginnote">Dunning and Ertl 描述 t-digest（技术报告 / 期刊化版本 2019 左右）。Greenwald–Khanna <em>SIGMOD</em> 2001 是经典确定摘要。本课不发明 arXiv 编号。</span></p><p><span class="marginnote">术语翻译：质心就是「一簇点的加权平均代表」——\\((m_i, c_i)\\) 里 \\(m_i\\) 是这簇数据的均值，\\(c_i\\) 是簇里有多少个点。t-digest 存几百个簇而不存全部点，等于把分布压成一串带权重的台阶。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现：按均值有序的质心缓冲，压缩时按权重限制合并邻居。查询：在质心序列上插值。合并：拼接再压缩，适合多机。不要用 HLL 估分位数。</p>',9)),(i(),l(o,null,{default:e(()=>[d(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%B5%81%E4%B8%8A%E7%9A%84%20x%22%5D%20--%3E%20C%5B%22%E5%B9%B6%E5%85%A5%E9%82%BB%E8%BF%91%E8%B4%A8%E5%BF%83%22%5D%0A%20%20C%20--%3E%20LIM%5B%22%E8%A7%84%E6%A8%A1%E9%99%90%E5%88%B6%3A%20%E5%B0%BE%E9%83%A8%E7%B0%87%E6%9B%B4%E5%B0%8F%22%5D%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%20q%22%5D%20--%3E%20INT%5B%22%E6%B2%BF%E8%B4%A8%E5%BF%83%E6%8F%92%E5%80%BC%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,"与蓄水池：池给出可复查的原始样本；digest 更省、专攻分位。与 CM：CM 键频次，digest 是值域分布。",-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[s("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"误差启发式依赖压缩与限制函数，实践中位数准、极端百分位仍要更多空间。合同写近似，监控延迟分位足够，金融结算精度不够则存精确结构。",-1)),(i(),l(o,null,{default:e(()=>[d(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20S1%5B%22%E5%88%86%E7%89%87%201%20%E7%9A%84%20digest%22%5D%20--%3E%20M%5B%22%E6%8B%BC%E6%8E%A5%E5%85%A8%E9%83%A8%E8%B4%A8%E5%BF%83%22%5D%0A%20%20S2%5B%22%E5%88%86%E7%89%87%202%20%E7%9A%84%20digest%22%5D%20--%3E%20M%0A%20%20S3%5B%22%E5%88%86%E7%89%87%203%20%E7%9A%84%20digest%22%5D%20--%3E%20M%0A%20%20M%20--%3E%20RC%5B%22%E6%8C%89%E9%99%90%E5%88%B6%E5%87%BD%E6%95%B0%E9%87%8D%E6%96%B0%E5%8E%8B%E7%BC%A9%22%5D%0A%20%20RC%20--%3E%20GQ%5B%22%E6%8F%92%E5%80%BC%E5%BE%97%E5%85%A8%E5%B1%80%E5%88%86%E4%BD%8D%E6%95%B0%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">数字实例：设限制函数把 P99 附近的簇压到几十个点一簇，而中位数附近的簇可含上万个点——同样是 100 亿条延迟记录、几百个质心，P99 的分辨粒度可能是微秒级，中位数只到毫秒级，这正符合「两端更细」的设计。</span></p><p><span class="marginnote">常见误区：初学者容易把质心当成采样点，以为 digest 里存着 100 条真实请求延迟。实际上每个质心是簇内所有值的加权均值，很可能没有任何一条真实记录恰好等于它，所以查询答案永远是近似而不是「第几个元素」。</span></p><p>概率课序结束。下一单元持久化：路径复制从线段树升到一般方法，接 Okasaki。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 DDSketch、HDR Histogram 写成百科列表，只承认同问题。并发无锁摘要后课另说。</p><p>后课默认：流分位数可用 t-digest/GK。不可变结构的共享从路径复制讲起。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>t-digest：质心近似分布，尾部更细，可合并。</li><li>GK 提供更经典的确定误差摘要。</li><li>下一单元：持久化与无锁结构。</li><li>出处：Dunning and Ertl；Greenwald and Khanna, <em>SIGMOD</em>, 2001。</li></ul>',8))])}const C=E(m,[["render",g]]);export{f as __pageData,C as default};
